package com.nequard.location; import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity @Table(name="locations") public class Location{@Id @GeneratedValue(strategy=GenerationType.UUID)UUID id;@Column(name="organization_id",nullable=false)UUID organizationId;@Column(nullable=false)String name;String address;Double latitude,longitude;Instant createdAt=Instant.now();public UUID getId(){return id;}public UUID getOrganizationId(){return organizationId;}public void setOrganizationId(UUID v){organizationId=v;}public String getName(){return name;}public void setName(String v){name=v;}public String getAddress(){return address;}public void setAddress(String v){address=v;}public Double getLatitude(){return latitude;}public void setLatitude(Double v){latitude=v;}public Double getLongitude(){return longitude;}public void setLongitude(Double v){longitude=v;}public Instant getCreatedAt(){return createdAt;}}